const items = $input.all();

return items.map((item) => {
  const job = item.json;

  const title = (job.title || '').toLowerCase();
  const subject = (job.email_subject || '').toLowerCase();

  let score = 0;
  const reasons = [];

  // Strong Data / AI / ML role relevance
  const highValueKeywords = [
    'data science',
    'data scientist',
    'machine learning',
    'ml engineer',
    'ai engineer',
    'artificial intelligence',
    'ai/ml',
    'data analyst',
    'data analytics',
    'business intelligence',
    'bi analyst',
    'data engineer'
  ];

  for (const keyword of highValueKeywords) {
    if (title.includes(keyword)) {
      score += 40;
      reasons.push(`Relevant role: ${keyword}`);
      break;
    }
  }

  // Related technical roles
  const relatedKeywords = [
    'analytics',
    'python',
    'power bi',
    'sql',
    'computer vision',
    'nlp',
    'deep learning',
    'predictive analytics',
    'research'
  ];

  for (const keyword of relatedKeywords) {
    if (title.includes(keyword)) {
      score += 15;
      reasons.push(`Related skill/domain: ${keyword}`);
      break;
    }
  }

  // Internship / student level
  const internshipKeywords = [
    'intern',
    'internship',
    'co-op',
    'coop',
    'trainee'
  ];

  if (internshipKeywords.some(keyword => title.includes(keyword))) {
    score += 35;
    reasons.push('Internship / student-level opportunity');
  }

  // Entry-level indicators
  const entryKeywords = [
    'junior',
    'entry level',
    'entry-level',
    'graduate',
    'associate'
  ];

  if (entryKeywords.some(keyword => title.includes(keyword))) {
    score += 25;
    reasons.push('Entry-level opportunity');
  }

  // Penalize senior roles
  const seniorKeywords = [
    'senior',
    'sr.',
    'sr ',
    'lead',
    'principal',
    'staff',
    'manager',
    'director',
    'head of',
    'architect'
  ];

  if (seniorKeywords.some(keyword => title.includes(keyword))) {
    score -= 45;
    reasons.push('Senior-level role');
  }

  // Data / ML alert context
  const alertKeywords = [
    'data science',
    'machine learning',
    'artificial intelligence',
    'data analyst',
    'data analytics',
    'data engineer',
    'business intelligence'
  ];

  if (alertKeywords.some(keyword => subject.includes(keyword))) {
    score += 10;
    reasons.push('Received from relevant LinkedIn alert');
  }

  // Easy Apply bonus
  if (job.easy_apply === true) {
    score += 5;
    reasons.push('Easy Apply available');
  }

  // Keep score between 0 and 100
  score = Math.max(0, Math.min(100, score));

  // Match level
  let matchLevel;

  if (score >= 75) {
    matchLevel = 'high';
  } else if (score >= 50) {
    matchLevel = 'medium';
  } else {
    matchLevel = 'low';
  }

  return {
    json: {
      ...job,
      match_score: score,
      match_level: matchLevel,
      filter_reason: reasons.join('; ')
    }
  };
});

const input = $input.first().json;
const html = input.html || '';

function decodeHtml(value = '') {
  return value
    .replace(/&middot;/gi, '·')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&apos;/gi, "'")
    .replace(/&#x27;/gi, "'")
    .replace(/&#(\d+);/g, (_, n) =>
      String.fromCharCode(Number(n))
    )
    .replace(/&#x([0-9a-f]+);/gi, (_, n) =>
      String.fromCharCode(parseInt(n, 16))
    );
}

function cleanText(value = '') {
  return decodeHtml(
    value
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
  );
}

// Split the LinkedIn email into individual job cards
const cards = html
  .split(/data-test-id="job-card"/i)
  .slice(1);

const jobs = [];

for (const card of cards) {

  // Find LinkedIn Job ID
  const jobLinkMatch = card.match(
    /href="([^"]*linkedin\.com\/comm\/jobs\/view\/(\d+)[^"]*)"/i
  );

  if (!jobLinkMatch) {
    continue;
  }

  const jobId = jobLinkMatch[2];

  // Find job title
  let titleMatch = card.match(
    new RegExp(
      `href="[^"]*jobcard_body_${jobId}[^"]*"[^>]*>([\\s\\S]*?)<\\/a>`,
      'i'
    )
  );

  // Fallback title extraction
  if (!titleMatch) {
    titleMatch = card.match(
      /<a[^>]*class="[^"]*text-md[^"]*text-color-brand[^"]*"[^>]*>([\s\S]*?)<\/a>/i
    );
  }

  const title = titleMatch
    ? cleanText(titleMatch[1])
    : null;

  // Find company + location
  const companyLocationMatch = card.match(
    /<p[^>]*class="[^"]*text-system-gray-100[^"]*"[^>]*>([\s\S]*?)<\/p>/i
  );

  let company = null;
  let location = null;

  if (companyLocationMatch) {
    const companyLocation = cleanText(
      companyLocationMatch[1]
    );

    const separatorIndex = companyLocation.indexOf('·');

    if (separatorIndex !== -1) {
      company = companyLocation
        .substring(0, separatorIndex)
        .trim();

      location = companyLocation
        .substring(separatorIndex + 1)
        .trim();
    } else {
      company = companyLocation;
    }
  }

  jobs.push({
    job_id: jobId,
    title,
    company,
    location,

    job_url:
      `https://www.linkedin.com/jobs/view/${jobId}`,

    source: 'LinkedIn',

    easy_apply:
      /Easy Apply/i.test(card),

    actively_recruiting:
      /Actively recruiting/i.test(card),

    email_subject:
      input.subject || null,

    received_at:
      input.date || null
  });
}

// Remove accidental duplicate jobs
const uniqueJobs = [];

const seen = new Set();

for (const job of jobs) {
  if (!seen.has(job.job_id)) {
    seen.add(job.job_id);
    uniqueJobs.push(job);
  }
}

return uniqueJobs.map(job => ({
  json: job
}));
